S = input()
T = input()
is_valid = False

# Check if T is derived by taking a subsequence of length 3 from S
t_lower = T.lower()
j = 0
for i in range(len(t_lower)):
    while j < len(S):
        if t_lower[i] == S[j]:
            j += 1
            break
        j += 1
    else:
        break
else:
    is_valid = True

# Check if T is derived by taking a subsequence of length 2 from S and appending 'X'
if not is_valid and T[-1] == 'X':
    t_lower = T[0:2].lower()
    j = 0
    for i in range(len(t_lower)):
        while j < len(S):
            if t_lower[i] == S[j]:
                j += 1
                break
            j += 1
        else:
            break
    else:
        is_valid = True

if is_valid:
    print("Yes")
else:
    print("No")
